<?php
require_once __DIR__ . '/includes/database.php';
require_once __DIR__ . '/includes/layout.php';
requireLogin();
$userQuery = database()->prepare('SELECT * FROM users WHERE id = :id'); $userQuery->execute(['id' => currentUser()['id']]); $user = $userQuery->fetch();
$menuId = filter_input(INPUT_GET, 'menu_id', FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST, 'menu_id', FILTER_VALIDATE_INT);
$menuQuery = database()->prepare('SELECT * FROM menus WHERE id = :id AND stock > 0'); $menuQuery->execute(['id' => $menuId]); $menu = $menuQuery->fetch();
if (!$menu) { header('Location: index.php#menus'); exit; }
$errors = [];
$data = ['delivery_address' => $user['address'], 'delivery_date' => '', 'delivery_time' => '', 'distance_km' => 0, 'quantity' => $menu['min_people']];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    foreach ($data as $field => $value) $data[$field] = trim($_POST[$field] ?? (string)$value);
    $quantity = (int)$data['quantity']; $distance = (float)$data['distance_km'];
    if (!$data['delivery_address'] || !$data['delivery_date'] || !$data['delivery_time']) $errors[] = 'Complète les informations de livraison.';
    if ($quantity < $menu['min_people']) $errors[] = 'Le minimum pour ce menu est de ' . $menu['min_people'] . ' personnes.';
    if ($distance < 0) $errors[] = 'La distance ne peut pas être négative.';
    if (!$errors) {
        $menuTotal = $menu['price'] * $quantity; $discount = $quantity >= $menu['min_people'] + 5 ? $menuTotal * .10 : 0; $delivery = stripos($data['delivery_address'], 'bordeaux') !== false ? 5 : 5 + (.59 * $distance); $total = $menuTotal - $discount + $delivery;
        database()->beginTransaction();
        try { $insert = database()->prepare('INSERT INTO customer_orders (user_id, menu_id, quantity, delivery_address, delivery_date, delivery_time, distance_km, menu_total, discount_amount, delivery_fee, total_amount, status) VALUES (:user_id, :menu_id, :quantity, :delivery_address, :delivery_date, :delivery_time, :distance_km, :menu_total, :discount_amount, :delivery_fee, :total_amount, "pending")'); $insert->execute(['user_id'=>$user['id'], 'menu_id'=>$menu['id'], 'quantity'=>$quantity, 'delivery_address'=>$data['delivery_address'], 'delivery_date'=>$data['delivery_date'], 'delivery_time'=>$data['delivery_time'], 'distance_km'=>$distance, 'menu_total'=>$menuTotal, 'discount_amount'=>$discount, 'delivery_fee'=>$delivery, 'total_amount'=>$total]); $orderId = database()->lastInsertId(); database()->prepare('INSERT INTO order_status_history (order_id, status) VALUES (:order_id, "pending")')->execute(['order_id'=>$orderId]); database()->commit(); header('Location: order-success.php?id=' . $orderId); exit; } catch (Throwable $e) { database()->rollBack(); $errors[] = 'La commande n’a pas pu être enregistrée.'; }
    }
}
pageHeader('Commander'); ?>
<main id="contenu" class="container py-5"><p class="eyebrow">Commande</p><h1>Finaliser votre prestation</h1><div class="row g-4"><section class="col-lg-7"><div class="order-panel"><h2 class="h4">Informations de livraison</h2><?php foreach ($errors as $error): ?><div class="alert alert-danger" role="alert"><?= htmlspecialchars($error) ?></div><?php endforeach; ?><form method="post" id="order-form" data-price="<?= htmlspecialchars($menu['price']) ?>" data-min="<?= htmlspecialchars($menu['min_people']) ?>"><input type="hidden" name="menu_id" value="<?= (int)$menu['id'] ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="customer_name">Nom</label><input readonly class="form-control" id="customer_name" value="<?= htmlspecialchars($user['first_name'] . ' ' . $user['last_name']) ?>"></div><div class="col-md-6"><label class="form-label" for="email">E-mail</label><input readonly class="form-control" id="email" value="<?= htmlspecialchars($user['email']) ?>"></div><div class="col-12"><label class="form-label" for="delivery_address">Adresse de prestation</label><input required class="form-control" name="delivery_address" id="delivery_address" value="<?= htmlspecialchars($data['delivery_address']) ?>"></div><div class="col-md-4"><label class="form-label" for="delivery_date">Date</label><input required type="date" class="form-control" name="delivery_date" id="delivery_date" min="<?= date('Y-m-d', strtotime('+3 days')) ?>" value="<?= htmlspecialchars($data['delivery_date']) ?>"></div><div class="col-md-4"><label class="form-label" for="delivery_time">Heure souhaitée</label><input required type="time" class="form-control" name="delivery_time" id="delivery_time" value="<?= htmlspecialchars($data['delivery_time']) ?>"></div><div class="col-md-4"><label class="form-label" for="distance_km">Distance hors Bordeaux (km)</label><input required type="number" min="0" step="0.1" class="form-control" name="distance_km" id="distance_km" value="<?= htmlspecialchars($data['distance_km']) ?>"></div><div class="col-md-6"><label class="form-label" for="quantity">Nombre de personnes</label><input required type="number" min="<?= (int)$menu['min_people'] ?>" class="form-control" name="quantity" id="quantity" value="<?= htmlspecialchars($data['quantity']) ?>"></div></div><button class="btn btn-primary mt-4" type="submit">Confirmer la commande</button></form></div></section><aside class="col-lg-5"><div class="order-summary"><h2 class="h4">Récapitulatif</h2><p><strong><?= htmlspecialchars($menu['title']) ?></strong><br>Minimum <?= (int)$menu['min_people'] ?> personnes · <?= number_format($menu['price'], 2, ',', ' ') ?> € / personne</p><dl><div><dt>Prix des menus</dt><dd id="menu-total">—</dd></div><div><dt>Remise (10 % dès <?= (int)$menu['min_people'] + 5 ?> personnes)</dt><dd id="discount">—</dd></div><div><dt>Livraison</dt><dd id="delivery-fee">—</dd></div><div class="total"><dt>Total</dt><dd id="total">—</dd></div></dl></div></aside></div></main><script src="assets/order.js"></script><?php pageFooter(); ?>
